// CSD_RATIONALE_BEGIN
// Root-cause analysis for attempt 35 (38.8% acc, 87.8% syn):
//
// Accuracy drop vs attempt 34 (49%→38.8%, −10.2pp):
//   Attempt 35 added Phase 3 triggers `openCount > closeCount` and `braceInTail`.
//   These caused Phase 3 to fire for examples where the model had ALREADY written a
//   CORRECT `<<A>>` span, then spuriously appended another `<<`. The evaluator uses
//   the LAST COMPLETE visible span, so for `<<A>><<` the evaluator would extract `A`
//   (correct). But Phase 3 closed the trailing `<<` with constrained-generated `<<B>>`
//   (wrong), making the extracted answer `B`. Five such examples flipped from correct
//   to wrong — exactly the 10.2pp drop (5/49).
//
// Remaining syntax failures (5 unclosed, 1 invalid):
//   For `closeCount == 0 && openCount > 0` (model opened `<<` but never closed),
//   attempt 35 called OpenConstrainedSpan (added a 3rd `<<`), then CloseSpanWithinBudget
//   from empty currentConstrained. The triple-`<<` context confused the close helper.
//   Fix: use EnterObservedConstrainedSpan (cost 0, no extra `<<`) so CloseSpanWithinBudget
//   generates content directly after the model's trailing `<<`, producing `<<EXPR>>`
//   as the last complete span the evaluator extracts.
//
// Strategy:
//   Phase 1: Unconstrained generation for maxSteps − spanBudget − 1 steps. Let the
//     model reason freely and write `<<int(expr)>>` naturally.
//   Phase 3: ONLY fires when closeCount == 0 (no complete span at all).
//     • openCount > 0: EnterObservedConstrainedSpan + CloseSpanWithinBudget(budget3)
//     • openCount == 0: OpenConstrainedSpan + CloseSpanWithinBudget(budget3)
//   For closeCount > 0 (including closeCount > 0 && openCount > closeCount):
//     Do NOT trigger Phase 3. The evaluator extracts the last COMPLETE span,
//     which may be the correct answer. Overwriting it would hurt accuracy.
//
// Expected: accuracy ≥ 44.9% (restores attempt 34's ~49%), syntax ≥ 90%.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   if-branch (insideConstrained on entry):
//     CloseSpanWithinBudget postcondition directly provides
//     `insideOut ==> parser.IsValidPrefix(currentOut)`. ✓
//
//   else-branch Phase 1 loop:
//     Invariant `!insideConstrainedOut` maintained throughout (never modified
//     inside the loop body, only UnconstrainedStep + append). Implication
//     vacuously true every iteration. ✓
//
//   else-branch Phase 3, openCount > 0 path:
//     EnterObservedConstrainedSpan sets insideConstrainedOut := true,
//     currentConstrainedOut := []. parser.IsValidPrefix([]) holds by method
//     requires. Then CloseSpanWithinBudget postcondition provides
//     `insideOut ==> parser.IsValidPrefix(currentOut)`. ✓
//
//   else-branch Phase 3, openCount == 0 path:
//     OpenConstrainedSpan sets insideConstrainedOut := true,
//     currentConstrainedOut := []. Same argument as above. ✓
//
//   else-branch Phase 3 skipped (closeCount > 0 or budget exhausted):
//     insideConstrainedOut remains false; implication vacuously true. ✓
//
// Invariant 2 (progress / length):
//   |generated| <= |generatedPrefix| + steps
//
//   if-branch: CloseSpanWithinBudget ensures |cg| <= |generated| + budget0.
//     steps := budget0. Since |generated|_0 = |generatedPrefix|, we get
//     |generated| <= |generatedPrefix| + budget0 = |generatedPrefix| + steps. ✓
//
//   else Phase 1 loop: Established at init (0 <= 0). Each iteration steps += 1.
//     EOS break: generated unchanged, steps incremented → bound preserved.
//     Non-EOS: generated grows by 1, steps grows by 1 → bound preserved. ✓
//
//   else Phase 3, openCount > 0: EnterObservedConstrainedSpan leaves generated
//     unchanged (cost 0). CloseSpanWithinBudget grows |generated| by at most
//     budget3 while steps += budget3. Total: phase1_steps + budget3 ≤
//     (maxSteps − spanBudget − 1) + spanBudget = maxSteps − 1 ≤ maxSteps. ✓
//
//   else Phase 3, openCount == 0: OpenConstrainedSpan grows |generated| by 1
//     and steps by 1. CloseSpanWithinBudget grows |generated| by at most budget3
//     while steps += budget3. Total: phase1_steps + 1 + budget3 ≤
//     (maxSteps − spanBudget − 1) + 1 + spanBudget = maxSteps. ✓
//
//   EOS and rejected suffix tokens inside CloseSpanWithinBudget consume step
//   budget without visible output growth, so visible length stays within the
//   budget bound. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "At the end, write the final answer as <<int(expr)>> using PLAIN variable names " +
    "(no curly braces — write n not {n}, write price not {price}). " +
    "Use only operators: +, -, *, /, //, (, ), int(). " +
    "Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 50;
  var steps: nat := 0;

  if insideConstrainedOut {
    // Entry with an already-open constrained span: close it within budget.
    if steps < maxSteps {
      var remaining0: nat := maxSteps - steps;
      var budget0: nat;
      if remaining0 < spanBudget {
        budget0 := remaining0;
      } else {
        budget0 := spanBudget;
      }
      var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget0
      );
      generated := cg0;
      insideConstrainedOut := ci0;
      currentConstrainedOut := cc0;
      steps := steps + budget0;
    }
  } else {
    // Phase 1: Full unconstrained generation — let the model reason and write <<int(expr)>>.
    var phase1Budget: nat;
    if maxSteps > spanBudget + 1 {
      phase1Budget := maxSteps - spanBudget - 1;
    } else {
      phase1Budget := maxSteps;
    }

    while steps < phase1Budget
      invariant 0 <= steps <= phase1Budget
      invariant phase1Budget <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut
      invariant currentConstrainedOut == []
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
    }

    // Phase 3: Check whether a complete visible span exists.
    var generatedStr := CSDHelpers.PrefixToString(generated);
    var closeCount := CSDHelpers.CountSubstring(generatedStr, ">>");
    var openCount  := CSDHelpers.CountSubstring(generatedStr, "<<");

    // Only intervene when there is NO complete visible span (closeCount == 0).
    // When closeCount > 0 (including the <<A>><<  pattern), the evaluator uses
    // the last COMPLETE span and may extract a correct answer; triggering Phase 3
    // would overwrite it with a constrained-generated expression (usually wrong).
    if closeCount == 0 && steps < maxSteps {
      if openCount > 0 {
        // Model opened a span (<<) but never closed it (no >>).
        // Enter the observed open span without appending another <<, so
        // CloseSpanWithinBudget appends content and >> after the existing <<.
        var og, oi, oc := helpers.EnterObservedConstrainedSpan(lm, generated);
        generated := og;
        insideConstrainedOut := oi;
        currentConstrainedOut := oc;
        // EnterObservedConstrainedSpan costs +0 steps.
      } else {
        // No span opened at all — open a fresh constrained span.
        var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
        generated := og;
        insideConstrainedOut := oi;
        currentConstrainedOut := oc;
        steps := steps + 1;
      }

      if insideConstrainedOut && steps < maxSteps {
        var remaining3: nat := maxSteps - steps;
        var budget3: nat;
        if remaining3 < spanBudget {
          budget3 := remaining3;
        } else {
          budget3 := spanBudget;
        }
        var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
        );
        generated := cg3;
        insideConstrainedOut := ci3;
        currentConstrainedOut := cc3;
        steps := steps + budget3;
      }
    }
  }

  cost := steps;

